insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('alert-eq-01', 'earthquake-gujarat', 'Aftershock Warning — Mw 5.2 Expected', 'India Meteorological Department (IMD) seismology division warns of possible aftershock Mw 5.0–5.5 within 6 hours of mainshock. All rescue teams advised to maintain safe egress routes. Occupants in structurally compromised buildings must evacuate immediately.', 'CRITICAL', '06:50:00 UTC+5:30', 'zone-ward-a', false) on conflict (id) do nothing;
insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('alert-eq-02', 'earthquake-gujarat', 'Structural Collapse — Anjar Market Sector', 'Three-storey commercial complex on Anjar Market Road has pancake-collapsed. NDRF Team 06 deployed with canine unit and acoustic sensors. Estimated 40–60 persons trapped. Blood bank and trauma unit on standby at Anjar Community Hall.', 'CRITICAL', '06:35:00 UTC+5:30', 'zone-ward-b', false) on conflict (id) do nothing;
insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('alert-eq-03', 'earthquake-gujarat', 'Gas Pipeline Rupture — Gandhidham Industrial', 'GAIL pipeline feeding Gandhidham industrial sector reported pressure drop indicating possible rupture. Isolation valve closed remotely. 500m exclusion zone enforced around Ward E perimeter. Fire tenders pre-positioned.', 'WARNING', '06:40:00 UTC+5:30', 'zone-ward-e', false) on conflict (id) do nothing;
insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('alert-eq-04', 'earthquake-gujarat', 'NDRF & Army Deployment — Column En Route', 'NDRF Battalions 06 and 12 (Gandhinagar) plus Indian Army 11 Infantry Division column dispatched from Bhuj Cantonment. ETA at forward staging area: 08:30 UTC+5:30. Helicopter reconnaissance by IAF Mi-17 underway over Kutch Mainland Fault trace.', 'INFO', '06:48:00 UTC+5:30', NULL, false) on conflict (id) do nothing;
