insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('al-cyc-01', 'cyclone-odisha', 'IMD Red Warning — Super Cyclone Landfall Imminent', 'India Meteorological Department has issued a RED WARNING for Puri-Ganjam coast. Super Cyclone (Cat-5, sustained winds 260 km/h, gusts 310 km/h) expected to make landfall between Puri and Konark within 6–8 hours. Storm surge of 4–6 meters forecast for low-lying coastal areas. All residents within 5 km of coastline must evacuate immediately to designated cyclone shelters.', 'CRITICAL', '2024-10-24T03:00:00Z', NULL, false) on conflict (id) do nothing;
insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('al-cyc-02', 'cyclone-odisha', 'Storm Surge Advisory — Chilika Lagoon Backflow', 'INCOIS storm surge model predicts 3–4 meter surge penetration through Chilika lagoon mouth. All lakeshore settlements including Satapada, Rambha, and Balugaon low-lying areas face severe inundation risk. Fishing boats must not venture into the lagoon. Evacuate to elevated shelters above 15 meters ASL.', 'CRITICAL', '2024-10-24T03:15:00Z', 'rz-cyc-03', false) on conflict (id) do nothing;
insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('al-cyc-03', 'cyclone-odisha', 'Wind Speed Escalation Warning — Puri District', 'Sustained wind speeds along the Puri coast have crossed 180 km/h and are escalating rapidly. Expected to reach 260 km/h at landfall. Kutcha and semi-pucca structures will not withstand these forces. All outdoor movement must cease. Shelter in reinforced concrete structures or designated cyclone bunkers only. Flying debris is a lethal hazard.', 'WARNING', '2024-10-24T03:30:00Z', 'rz-cyc-01', false) on conflict (id) do nothing;
insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('al-cyc-04', 'cyclone-odisha', 'Fishermen Warning — Bay of Bengal', 'All fishing operations in the Bay of Bengal west-central and adjoining areas MUST cease immediately. Sea condition: phenomenal (wave height 12–14 meters). Fishermen who are already at sea must seek nearest port shelter. Do not attempt to return to home port if distance exceeds 50 nautical miles. Ganjam, Puri, and Jagatsinghpur harbors are CLOSED until further notice.', 'WARNING', '2024-10-24T02:30:00Z', NULL, false) on conflict (id) do nothing;
