insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('alert-incois', 'tsunami-tamilnadu', 'INCOIS Tsunami Warning — RED Alert', 'Indian National Centre for Ocean Information Services (INCOIS) has issued a RED tsunami warning for Tamil Nadu coast. Mw 8.7 earthquake detected on the Andaman-Sumatra Subduction Zone at 01:58 UTC+5:30. Estimated wave arrival at Chennai coast: 03:30 UTC+5:30. Expected wave height: 8–12 m. All coastal residents within 2 km of shoreline or below 15 m elevation must evacuate immediately.', 'CRITICAL', '2024-09-02T02:05:00+05:30', NULL, false) on conflict (id) do nothing;
insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('alert-seismic', 'tsunami-tamilnadu', 'Seismic Trigger Notification — Andaman Islands', 'IMD Seismology Division confirms Mw 8.7 shallow thrust earthquake at depth 22 km, epicentre 3.3°N 95.8°E (Simeulue Island, Sumatra). Severe rupture along 400 km of subduction zone. Aftershocks Mw 6.2–7.1 expected. Tsunami generation confirmed by DART buoy network and PTWC.', 'CRITICAL', '2024-09-02T02:00:00+05:30', NULL, false) on conflict (id) do nothing;
insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('alert-siren', 'tsunami-tamilnadu', 'Coastal Evacuation Sirens Activated', 'All 47 tsunami warning sirens along the Chennai–Kanchipuram coast have been activated. Public address system broadcasting in Tamil, English, and Hindi. Coastal police deploying door-to-door alerts in fishing hamlets. Beach areas sealed by police. Do NOT return to coastal areas until official all-clear from INCOIS.', 'WARNING', '2024-09-02T02:15:00+05:30', NULL, false) on conflict (id) do nothing;
insert into alerts (id, scenario_id, title, message, severity, timestamp, zone_id, read) values ('alert-navy', 'tsunami-tamilnadu', 'Indian Navy — Eastern Naval Command Rescue Deployment', 'INS Adyar and 3 fast interceptor craft deployed from Chennai naval base for post-impact search and rescue. 2 Sea King helicopters on standby at INS Rajali, Arakkonam. NDRF 4th Battalion (Arakkonam) mobilized with 8 rescue teams. Navy divers staged at Royapuram harbour.', 'INFO', '2024-09-02T02:30:00+05:30', NULL, false) on conflict (id) do nothing;
